<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {audioMidiCapabilities} from './audio-midi-state.js';
 import {audioMidiMenus} from './audio-midi-menus.js';
 import {createBrowserPreviews} from './audio-midi-preview.js';
 import {describeAudioUtilityControls,focusAudioUtilityControl} from './audio-midi-native.js';
 import './audio-midi.css';
 let {window,state: audioMidiState,profile,execute,registerView,sound,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),from=$state(''),to=$state(''),memberIds=$state([]),compositeName=$state('Aggregate Device'),configurationName=$state('New Configuration'),outputPort=$state(1),inputPort=$state(1),dragFrom=$state(null);
 let originalState,originalWindow,originalSound,originalProfile,retired=false,previews,facade;
 const w=$derived(audioMidiState.windows.find(s=>s.windowId===window.id));const cap=$derived(audioMidiCapabilities(profile));const config=$derived(audioMidiState.configurations.find(c=>c.id===w?.configurationId));const device=$derived((w?.direction==='input'?sound?.inputs:sound?.outputs)?.find(d=>d.id===w?.deviceId));const format=$derived(sound?.audioMidi?.formats.find(f=>f.id===w?.deviceId&&f.direction===w?.direction));const composite=$derived(sound?.audioMidi?.composites.find(d=>d.id===w?.deviceId));const midi=$derived(config?.devices.find(d=>d.id===w?.midiDeviceId));const menus=$derived(audioMidiMenus({state: audioMidiState,windowId:window.id}));
 const current=()=>!retired&&root?.isConnected&&audioMidiState===originalState&&window===originalWindow&&sound===originalSound&&profile===originalProfile&&available&&active;
 async function command(suffix,payload={}){if(!current())return;const response=await execute(`audiomidi.${suffix}`,{windowId:window.id},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'Operation unavailable.';return response;}
 const modify=(payload)=>command('device',{operation:'edit',id:midi.id,...payload});
 function toggleMember(id){memberIds=memberIds.includes(id)?memberIds.filter(v=>v!==id):[...memberIds,id];}
 function connect(){command('connection',{operation:'connect',from,to,output:outputPort,input:inputPort});}
 onMount(()=>{originalState=audioMidiState;originalWindow=window;originalSound=sound;originalProfile=profile;previews=createBrowserPreviews(root);facade={available:current,describe:()=>({appId:'audiomidi',windowId:window.id,pane:w?.pane,controls:describeAudioUtilityControls(root),browserAudio:!!(globalThis.AudioContext??globalThis.webkitAudioContext)}),focus:async(id,guard)=>{await tick();if(!current()||guard()!==true)return false;return focusAudioUtilityControl(root,id);},playTone:previews.playTone};registerView?.(window.id,facade);return()=>{retired=true;previews.dispose();registerView?.(originalWindow.id,null,facade);};});
</script>
<section bind:this={root} class="audio-midi-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} aria-label={cap.label}>
 <header class="av-title">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom}/>{/if}<strong>{w?.pane==='midi'?'MIDI Studio':cap.windows?cap.label:'Audio Devices'}</strong></header>
 {#if w&&sound?.audioMidi}
 <nav aria-label="Application menus">{#each menus as menu}<button onclick={()=>command('sheet',{menu:w.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>
 {#if w.menu}<div class="av-menu" role="menu">{#each menus.find(m=>m.id===w.menu)?.children??[] as item}<button role="menuitem" disabled={!item.enabled} onclick={async()=>{const r=await command(item.request.command.slice(10),item.request.payload);if(r?.status==='applied')command('sheet',{menu:null});}}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 <p class="av-disclosure">{cap.disclosure} Browser previews play locally; fictional device selections never reconfigure hardware.</p>
 <div class="av-body" inert={!active||!available}>
 {#if w.pane==='audio'}
 <aside class="av-devices">{#each [['output',sound.outputs],['input',sound.inputs]] as [direction,rows]}<h4>{direction==='input'?'Input':'Output'}</h4>{#each rows as row}<button class:selected={w.deviceId===row.id&&w.direction===direction} disabled={!row.available} data-av-control={`device:${row.id}`} onclick={()=>command('select',{deviceId:row.id,direction})}><span>◉</span><div><strong>{row.name}</strong><small>{sound[direction==='input'?'inputDeviceId':'outputDeviceId']===row.id?'Default ':''}{direction} · {row.available?'local device':'offline'}</small></div></button>{/each}{/each}{#each sound.audioMidi.composites as row}<button class:selected={w.deviceId===row.id} onclick={()=>command('select',{deviceId:row.id})}><span>▦</span><div><strong>{row.name}</strong><small>{row.kind}</small></div></button>{/each}<details><summary>＋ Create Device</summary><input aria-label="Composite name" maxlength="128" bind:value={compositeName}/>{#each [...sound.outputs,...sound.inputs].filter(d=>d.available) as d}<label><input type="checkbox" checked={memberIds.includes(d.id)} onchange={()=>toggleMember(d.id)}/>{d.name}</label>{/each}<button disabled={memberIds.length<2} onclick={()=>command('composite',{operation:'create',kind:'aggregate',name:compositeName,memberIds})}>Create Aggregate Device</button><button disabled={memberIds.length<2||memberIds.some(id=>!sound.outputs.some(d=>d.id===id))} onclick={()=>command('composite',{operation:'create',kind:'multi-output',name:compositeName,memberIds})}>Create Multi-Output Device</button></details></aside>
 <main class="av-properties">{#if device&&format}<h2>{device.name}</h2><div class="av-tabs"><button class:selected={w.direction==='input'} disabled={!sound.inputs.some(d=>d.id===device.id)} onclick={()=>command('select',{direction:'input'})}>Input</button><button class:selected={w.direction==='output'} disabled={!sound.outputs.some(d=>d.id===device.id)} onclick={()=>command('select',{direction:'output'})}>Output</button></div><label>Clock Source: <select disabled><option>Default · authored device</option></select></label><label>Format: <select data-av-control="sampleRate" value={format.sampleRate} onchange={e=>command('format',{deviceId:device.id,direction:w.direction,sampleRate:Number(e.currentTarget.value)})}>{#each [44100,48000,96000] as rate}<option value={rate}>{rate.toLocaleString()} Hz</option>{/each}</select><select aria-label="Bit depth" value={format.bitDepth} onchange={e=>command('format',{deviceId:device.id,direction:w.direction,bitDepth:Number(e.currentTarget.value)})}>{#each [16,24,32] as bits}<option value={bits}>{format.channels.length}ch-{bits}bit</option>{/each}</select></label><div class="av-channel-table"><div>Channel</div><div>Volume</div><div>Value</div><label>Master</label><input aria-label="Device master volume" data-av-control="master" type="range" min="0" max="100" disabled={!device.adjustable} value={w.direction==='input'?device.gain:device.volume} oninput={e=>command('master',{deviceId:device.id,direction:w.direction,value:Number(e.currentTarget.value)})}/><output>{w.direction==='input'?device.gain:device.volume}%</output>{#each format.channels as channel,index}<label>{index+1}</label><input aria-label={`Channel ${index+1} volume`} type="range" min="0" max="100" disabled={!device.adjustable} value={channel.gain} oninput={e=>command('channel',{deviceId:device.id,direction:w.direction,channel:index+1,gain:Number(e.currentTarget.value)})}/><output>{channel.gain}%</output>{/each}</div><button onclick={()=>command('route',{deviceId:device.id,kind:w.direction})}>Use This Device for Sound {w.direction==='input'?'Input':'Output'}</button>{#if w.direction==='output'}<button onclick={()=>command('route',{deviceId:device.id,kind:'alert'})}>Play Alerts Through This Device</button><button data-av-control="speakers" onclick={()=>command('sheet',{sheet:'speakers'})}>Configure Speakers…</button>{/if}
 {:else if composite}<h2><input aria-label="Composite name" value={composite.name} maxlength="128" onchange={e=>command('composite',{operation:'edit',id:composite.id,name:e.currentTarget.value})}/></h2><p>{composite.kind==='aggregate'?'Combined authored input/output channels':'Mirrored local output configuration'} — no host routing.</p><label>Clock Source <select value={composite.clockId} onchange={e=>command('composite',{operation:'edit',id:composite.id,clockId:e.currentTarget.value,driftIds:composite.driftIds.filter(id=>id!==e.currentTarget.value)})}>{#each composite.memberIds as id}<option value={id}>{[...sound.outputs,...sound.inputs].find(d=>d.id===id)?.name}</option>{/each}</select></label><h3>Use / Drift Correction</h3>{#each [...sound.outputs,...sound.inputs].filter(d=>d.available&&(composite.kind==='aggregate'||sound.outputs.includes(d))) as d}<label><input type="checkbox" checked={composite.memberIds.includes(d.id)} onchange={()=>command('composite',{operation:'edit',id:composite.id,memberIds:composite.memberIds.includes(d.id)?composite.memberIds.filter(id=>id!==d.id):[...composite.memberIds,d.id],driftIds:composite.driftIds.filter(id=>id!==d.id)})}/>{d.name}<input aria-label={`Drift correction ${d.name}`} type="checkbox" disabled={!composite.memberIds.includes(d.id)||d.id===composite.clockId} checked={composite.driftIds.includes(d.id)} onchange={()=>command('composite',{operation:'edit',id:composite.id,driftIds:composite.driftIds.includes(d.id)?composite.driftIds.filter(id=>id!==d.id):[...composite.driftIds,d.id]})}/></label>{/each}<button onclick={()=>command('composite',{operation:'delete',id:composite.id})}>Remove Device</button>{:else}<p>Select an available audio device.</p>{/if}</main>
 {:else}
 <main class="av-midi"><div class="av-toolbar"><label>MIDI Configuration <select value={config.id} onchange={e=>command('configuration',{operation:'select',id:e.currentTarget.value})}>{#each audioMidiState.configurations as c}<option value={c.id}>{c.name}</option>{/each}</select></label><button onclick={()=>command('device',{operation:'create'})}>＋ Add Device</button><button aria-pressed={w.testMode} onclick={()=>command('test',{operation:w.testMode?'disable':'enable'})}>Test MIDI Setup</button></div><details><summary>Manage Configurations</summary><input aria-label="Configuration name" bind:value={configurationName} maxlength="128"/><button onclick={()=>command('configuration',{operation:'create',name:configurationName})}>New</button><button onclick={()=>command('configuration',{operation:'rename',id:config.id,name:configurationName})}>Rename</button><button disabled={audioMidiState.configurations.length===1} onclick={()=>command('configuration',{operation:'delete',id:config.id})}>Delete</button></details>
 <div class="av-studio">{#each config.devices as d}<div class="av-midi-device" class:selected={w.midiDeviceId===d.id} class:lit={w.litIds.includes(d.id)} style:left={`${d.x}px`} style:top={`${d.y}px`} role="group" aria-label={d.name}><div class="av-ports">{#each Array(d.inputPorts) as _,i}<button aria-label={`${d.name} input ${i+1}`} ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();if(dragFrom)command('connection',{operation:'connect',from:dragFrom.id,output:dragFrom.port,to:d.id,input:i+1});dragFrom=null;}}>↑{i+1}</button>{/each}{#each Array(d.outputPorts) as _,i}<button draggable="true" ondragstart={()=>dragFrom={id:d.id,port:i+1}} aria-label={`${d.name} output ${i+1}`} onclick={()=>w.testMode?command('test',{operation:'midi',deviceId:d.id}):command('select',{midiDeviceId:d.id})}>↓{i+1}</button>{/each}</div><button class="av-device-icon" data-av-control={`midi:${d.id}`} onclick={()=>command('select',{midiDeviceId:d.id})} ondblclick={()=>{command('select',{midiDeviceId:d.id});command('sheet',{sheet:'properties'});}}>▥<strong>{d.name}</strong></button></div>{/each}</div>
 <div class="av-connections"><h3>Port Connections</h3>{#each config.connections as e}<div>{config.devices.find(d=>d.id===e.from)?.name} [{e.output}] → {config.devices.find(d=>d.id===e.to)?.name} [{e.input}] <button aria-label="Disconnect" onclick={()=>command('connection',{operation:'disconnect',id:e.id})}>×</button></div>{/each}<select aria-label="Source device" bind:value={from}><option value="">Output device</option>{#each config.devices.filter(d=>d.outputPorts>0) as d}<option value={d.id}>{d.name}</option>{/each}</select><input aria-label="Output port" type="number" min="1" max="16" bind:value={outputPort}/><select aria-label="Destination device" bind:value={to}><option value="">Input device</option>{#each config.devices.filter(d=>d.inputPorts>0) as d}<option value={d.id}>{d.name}</option>{/each}</select><input aria-label="Input port" type="number" min="1" max="16" bind:value={inputPort}/><button disabled={!from||!to} onclick={connect}>Connect</button></div></main>
 {/if}</div>
 {#if w.sheet!=='none'}<div class="av-sheet" role="dialog" aria-label={w.sheet}><h2>{w.sheet==='speakers'?'Configure Speakers':w.sheet==='properties'?'MIDI Device Properties':w.sheet==='preferences'?'Preferences':'Audio MIDI Setup Help'}</h2>{#if w.sheet==='speakers'&&format}<p>Choose each local speaker channel. Tests are stereo browser previews, not hardware verification.</p>{#each format.speakers as assignment,index}<label>Speaker {index+1}<select value={assignment} onchange={e=>command('speakers',{deviceId:device.id,assignments:format.speakers.map((n,i)=>i===index?Number(e.currentTarget.value):n)})}>{#each format.channels as _,i}<option value={i+1}>Channel {i+1}</option>{/each}</select><button onclick={()=>command('test',{operation:'speaker',deviceId:device.id,channel:assignment})}>Test</button></label>{/each}{:else if w.sheet==='properties'&&midi}{#each ['name','manufacturer','model'] as key}<label>{key}<input maxlength="128" value={midi[key]} onchange={e=>modify({[key]:e.currentTarget.value})}/></label>{/each}{#each [['inputPorts','Input ports',0,16],['outputPorts','Output ports',0,16],['channel','MIDI channel',1,16],['x','Position X',0,1200],['y','Position Y',0,900]] as [key,label,min,max]}<label>{label}<input type="number" {min} {max} value={midi[key]} onchange={e=>modify({[key]:Number(e.currentTarget.value)})}/></label>{/each}<button onclick={()=>command('device',{operation:'delete',id:midi.id})}>Remove Device</button>{:else if w.sheet==='preferences'}<label>Test note<input type="number" min="0" max="127" value={audioMidiState.preferences.testNote} onchange={e=>command('preferences',{testNote:Number(e.currentTarget.value)})}/></label><label>Velocity<input type="number" min="1" max="127" value={audioMidiState.preferences.testVelocity} onchange={e=>command('preferences',{testVelocity:Number(e.currentTarget.value)})}/></label><label><input type="checkbox" checked={audioMidiState.preferences.playTests} onchange={e=>command('preferences',{playTests:e.currentTarget.checked})}/>Play local browser tone during MIDI tests</label>{:else}<p>{cap.disclosure}</p><p>Audio Devices references the original shared Sound devices and master volumes. Aggregate and Multi-Output rows describe fictional configurations only. MIDI Studio connects explicit output/input ports; Test MIDI traverses these real local connections and illuminates reached devices. Browser audio requires availability and may require a user gesture.</p>{/if}<button onclick={()=>command('sheet',{sheet:'none'})}>Done</button></div>{/if}
 <footer role="status">{message||w.status||'Authored local hardware · no real MIDI or audio reconfiguration'}</footer>
 {:else}<p role="alert">Original shared sound metadata or utility session unavailable.</p>{/if}
</section>
